add_action( 'admin_footer-post.php', 'perfectpixel_max_product_categories' );
add_action( 'admin_footer-post-new.php', 'perfectpixel_max_product_categories' );

function perfectpixel_max_product_categories() {
	if ( 'product' !== get_current_screen()->post_type ) {
		return;
	}
	$max = max( 1, (int) '{{max_product_categories}}' );
	$cfg = array(
		'max'     => $max,
		'message' => str_replace( '%d', $max, '{{max_categories_message}}' ),
	);
	?>
	<script>
	( function ( cfg ) {
		var list = document.getElementById( 'product_catchecklist' );
		if ( ! list ) {
			return;
		}
		list.addEventListener( 'change', function ( e ) {
			if ( e.target.checked && list.querySelectorAll( 'input[type=checkbox]:checked' ).length > cfg.max ) {
				e.target.checked = false;
				window.alert( cfg.message );
			}
		} );
	} )( <?php echo wp_json_encode( $cfg ); ?> );
	</script>
	<?php
}
